package dev.vitrail.glsl;

import java.util.ArrayDeque;
import java.util.Deque;
import java.util.HashSet;
import java.util.LinkedHashMap;
import java.util.Map;
import java.util.Set;
import java.util.function.BiFunction;
import java.util.regex.Matcher;
import java.util.regex.Pattern;

/**
 * Splices code generated by Chunks Fade In into the translated terrain stages. No animation
 * timing or fade curves live here: the optional mod owns both those and the generated code.
 */
public final class ChunkFadeShader {
	private static final Pattern OUTPUT = Pattern.compile(
			"layout\\s*\\(\\s*location\\s*=\\s*(\\d+)\\s*\\)\\s*out\\s+(float|vec[234]|uint|uvec[234])\\s+(\\w+)\\s*;");
	private static final Set<String> VECTOR_TYPES = Set.of("vec2", "vec3", "vec4");
	private static final Set<String> PACKERS = Set.of("packUnorm2x16", "packSnorm2x16",
			"packHalf2x16", "packUnorm4x8", "packSnorm4x8");
	private static final Set<String> ARGUMENT_PUNCTUATION = Set.of(".", ",", "(", ")");
	private static final Set<String> NON_TYPES = Set.of("return", "case", "else", "if", "break",
			"continue", "discard", "in", "out", "uniform", "const", "flat", "smooth", "centroid");
	private static final Map<String, String> MARKERS = Map.of(
			"CHUNKS_FADE_IN_NO_INJECT", "_cfi_noInjectMarker",
			"CHUNKS_FADE_IN_NO_MOD_INJECT", "_cfi_noInjectModMarker",
			"CHUNKS_FADE_IN_NO_VERT_MOD_INJECT", "_cfi_noInjectVertModMarker",
			"CHUNKS_FADE_IN_NO_FRAG_MOD_INJECT", "_cfi_noInjectFragModMarker");

	private ChunkFadeShader() {
	}

	/** Displaces the decoded section local position before it is placed inside its region. */
	public static String vertex(String source, String declarations, String init) {
		TokenStream tokens = new TokenStream(GlslLexer.lex(source));
		int function = function(tokens, SodiumVertex.PROLOGUE);
		int local = -1;
		for (int i = function; i < tokens.size(); i++) {
			if (tokens.get(i).identifier("ofLocal")) {
				local = i;
				break;
			}
		}
		if (local < 0) {
			throw new IllegalArgumentException("Missing terrain local position");
		}
		int end = local;
		while (end < tokens.size() && !tokens.get(end).operator(";")) {
			end++;
		}
		if (end == tokens.size()) {
			throw new IllegalArgumentException("Unterminated terrain local position");
		}
		tokens.inject(end, ";\n" + init + "\n");
		int start = tokens.significantBefore(function);
		tokens.inject(start, declarations + "\nvoid");
		return tokens.join();
	}

	/** Wraps the whole entry point so an early return cannot bypass the fade. */
	public static String fragment(String source, String declarations, String tail) {
		return header(source, declarations + "\n#define main ofCfiMain\n")
				+ "\n#undef main\nvoid main() {\nofCfiMain();\n" + tail + "\n}\n";
	}

	/** Carry live opt-out directives through translation, including cached translations. */
	public static String preserveMarkers(String source, Map<String, String> defines) {
		StringBuilder text = new StringBuilder(source);
		MARKERS.entrySet().stream().sorted(Map.Entry.comparingByKey()).forEach(marker -> {
			if (defines.containsKey(marker.getKey())) {
				text.append("\nint ").append(marker.getValue()).append(";\n");
			}
		});
		return text.toString();
	}

	/** Only identifiers count; a comment mentioning a directive cannot turn an effect off. */
	public static boolean marker(String source, String name) {
		return GlslLexer.lex(source).stream().anyMatch(token -> token.identifier(name));
	}

	private record Colour(String type, String name) {
	}

	private static Colour firstOutput(String source) {
		StringBuilder code = new StringBuilder();
		for (GlslLexer.Token token : GlslLexer.lex(source)) {
			code.append(token.kind() == GlslLexer.Kind.COMMENT ? " " : token.text());
		}
		Matcher match = OUTPUT.matcher(code);
		Colour first = null;
		int location = Integer.MAX_VALUE;
		while (match.find()) {
			int next = Integer.parseInt(match.group(1));
			if (next < location) {
				location = next;
				first = new Colour(match.group(2), match.group(3));
			}
		}
		return first;
	}

	/**
	 * Fade unpacked colour before it is encoded into a G-buffer. Integer targets are never mixed
	 * with a sky colour. Unsupported packing is refused rather than corrupting encoded material data.
	 * The operation receives a colour expression and the matching sky-channel swizzle.
	 */
	public static String fade(String source, String declarations,
			BiFunction<String, String, String> operation, String scalarOperation) {
		Colour output = firstOutput(source);
		if (output == null) {
			throw new IllegalArgumentException("No supported first colour output");
		}
		TokenStream tokens = new TokenStream(GlslLexer.lex(source));
		Map<Integer, StringBuilder> prefixes = new LinkedHashMap<>();
		Map<Integer, StringBuilder> suffixes = new LinkedHashMap<>();
		Map<String, String> copies = new LinkedHashMap<>();
		Set<String> usedNames = new HashSet<>();
		for (GlslLexer.Token token : tokens) {
			if (token.kind() == GlslLexer.Kind.IDENTIFIER) {
				usedNames.add(token.text());
			}
		}
		int nextCopy = 0;
		boolean packing = false;
		for (int i = 0; i < tokens.size(); i++) {
			GlslLexer.Token token = tokens.get(i);
			if (token.kind() != GlslLexer.Kind.IDENTIFIER || token.directive() != null
					|| !token.text().contains("pack")) {
				continue;
			}
			int open = tokens.significantAfter(i);
			if (open < 0 || !tokens.get(open).operator("(")) {
				continue;
			}
			int start = i;
			while (start > 0 && !tokens.get(start - 1).operator(";")
					&& !tokens.get(start - 1).operator("{")
					&& !tokens.get(start - 1).operator("}")) {
				start--;
			}
			int lhs = start;
			while (lhs < i && (tokens.get(lhs).trivia()
					|| tokens.get(lhs).kind() == GlslLexer.Kind.NEWLINE)) {
				lhs++;
			}
			int target = lhs;
			while (target < i && !tokens.get(target).identifier(output.name())) {
				target++;
			}
			if (target == i) {
				continue;
			}
			int equals = tokens.significantAfter(target);
			if (equals >= 0 && tokens.get(equals).operator(".")) {
				equals = tokens.significantAfter(equals);
				equals = equals < 0 ? -1 : tokens.significantAfter(equals);
			}
			if (equals < 0 || !tokens.get(equals).operator("=")) {
				for (int at = target; at < i; at++) {
					if (tokens.get(at).operator("=")) {
						throw new IllegalArgumentException("Indexed or compound packed-output assignment");
					}
				}
				continue;
			}
			packing = true;
			if (lhs != target || !PACKERS.contains(token.text())) {
				throw new IllegalArgumentException("Unsupported control flow or custom colour packing");
			}
			int close = tokens.matchingBracket(open);
			if (close < 0) {
				throw new IllegalArgumentException("Unterminated colour packing call");
			}
			int end = close;
			while (end < tokens.size() && !tokens.get(end).operator(";")) {
				end++;
			}
			if (end == tokens.size()) {
				throw new IllegalArgumentException("Unterminated colour packing assignment");
			}
			boolean found = false;
			for (int arg = open + 1; arg < close; arg++) {
				GlslLexer.Token value = tokens.get(arg);
				if (value.kind() != GlslLexer.Kind.IDENTIFIER) {
					if (value.kind() == GlslLexer.Kind.OPERATOR
							&& !ARGUMENT_PUNCTUATION.contains(value.text())) {
						throw new IllegalArgumentException("Colour packing argument is not a direct colour");
					}
					continue;
				}
				if (channels(value.text()) || VECTOR_TYPES.contains(value.text())) {
					continue;
				}
				int after = tokens.significantAfter(arg);
				if (after >= 0 && tokens.get(after).operator("(")) {
					throw new IllegalArgumentException("Colour packing requires a variable, not a function call");
				}
				String key = lhs + ":" + value.text();
				String copy = copies.get(key);
				if (copy == null) {
					if (!(value.text().contains("color") || value.text().contains("colour"))) {
						throw new IllegalArgumentException("Cannot identify colour before G-buffer packing");
					}
					String type = vectorType(tokens, value.text(), lhs);
					do {
						copy = "ofCfiPacked" + nextCopy++;
					} while (!usedNames.add(copy));
					String swizzle = type.equals("vec2") ? "rg" : "rgb";
					String expression = type.equals("vec2") ? copy : copy + ".rgb";
					prefixes.computeIfAbsent(lhs, ignored -> new StringBuilder("{\n"))
							.append(type).append(' ').append(copy).append(" = ").append(value.text()).append(";\n")
							.append(operation.apply(expression, swizzle));
					copies.put(key, copy);
					suffixes.putIfAbsent(end, new StringBuilder("\n}"));
				}
				tokens.replace(arg, copy);
				found = true;
			}
			if (!found) {
				throw new IllegalArgumentException("Packing call has no direct colour argument");
			}
			i = close;
		}
		if (packing) {
			prefixes.forEach((at, text) -> tokens.inject(at, text + tokens.get(at).text()));
			suffixes.forEach((at, text) -> tokens.inject(at, tokens.get(at).text() + text));
			return header(tokens.join(), declarations);
		}
		// Locals or helper returns can carry encoded bits into a floating output. Without an
		// inline packing assignment, treating that output as a colour would corrupt the payload.
		for (GlslLexer.Token token : tokens) {
			if (token.identifier("uintBitsToFloat") || token.identifier("intBitsToFloat")) {
				throw new IllegalArgumentException("Unresolved integer bitcast in floating colour output");
			}
		}
		String tail = switch (output.type()) {
			case "float" -> scalarOperation.replace("ofCfiColour", output.name());
			case "vec2" -> operation.apply(output.name(), "rg");
			case "vec3" -> operation.apply(output.name(), "rgb");
			case "vec4" -> operation.apply(output.name() + ".rgb", "rgb");
			default -> throw new IllegalArgumentException("Packed first output has no supported colour assignment");
		};
		return fragment(source, declarations, tail);
	}

	private static boolean channels(String name) {
		return !name.isEmpty() && (name.chars().allMatch(c -> "rgba".indexOf(c) >= 0)
				|| name.chars().allMatch(c -> "xyzw".indexOf(c) >= 0));
	}

	private static String vectorType(TokenStream tokens, String name, int before) {
		Deque<Map<String, String>> scopes = new ArrayDeque<>();
		scopes.push(new LinkedHashMap<>());
		int parentheses = 0;
		for (int i = 0; i < before; i++) {
			GlslLexer.Token token = tokens.get(i);
			if (token.operator("(")) {
				parentheses++;
			} else if (token.operator(")")) {
				parentheses--;
			} else if (token.operator("{")) {
				Map<String, String> block = new LinkedHashMap<>();
				int previous = tokens.significantBefore(i);
				// Parameters belong only to the function body they precede, never to the globals.
				if (scopes.size() == 1 && previous >= 0 && tokens.get(previous).operator(")")) {
					int open = previous;
					int depth = 1;
					while (--open >= 0 && depth > 0) {
						if (tokens.get(open).operator(")")) {
							depth++;
						} else if (tokens.get(open).operator("(")) {
							depth--;
						}
					}
					for (int arg = open + 1; arg < previous; arg++) {
						declaration(tokens, arg, block);
					}
				}
				scopes.push(block);
			} else if (token.operator("}")) {
				if (scopes.size() > 1) {
					scopes.pop();
				}
			} else if (parentheses == 0) {
				declaration(tokens, i, scopes.peek());
			} else if (scopes.size() > 1) {
				Map<String, String> nested = new LinkedHashMap<>();
				declaration(tokens, i, nested);
				nested.keySet().forEach(variable -> scopes.peek().put(variable, "unsupported"));
			}
		}
		for (Map<String, String> scope : scopes) {
			String type = scope.get(name);
			if (type != null) {
				if (VECTOR_TYPES.contains(type)) {
					return type;
				}
				break;
			}
		}
		throw new IllegalArgumentException("Unknown vector type for packed colour " + name);
	}

	private static void declaration(TokenStream tokens, int at, Map<String, String> scope) {
		if (tokens.get(at).kind() != GlslLexer.Kind.IDENTIFIER || tokens.get(at).directive() != null) {
			return;
		}
		int type = tokens.significantBefore(at);
		int after = tokens.significantAfter(at);
		if (type >= 0 && tokens.get(type).kind() == GlslLexer.Kind.IDENTIFIER
				&& !NON_TYPES.contains(tokens.get(type).text())
				&& (after < 0 || !tokens.get(after).operator("("))) {
			String name = tokens.get(at).text();
			String value = tokens.get(type).text();
			String previous = scope.get(name);
			scope.put(name, previous == null || previous.equals(value) ? value : "unsupported");
		}
	}

	private static String header(String source, String declarations) {
		int versionEnd = source.indexOf('\n');
		if (!source.startsWith("#version") || versionEnd < 0) {
			throw new IllegalArgumentException("Missing translated shader version");
		}
		int headerEnd = versionEnd + 1;
		int offset = 0;
		for (GlslLexer.Token token : GlslLexer.lex(source)) {
			if ("extension".equals(token.directive())) {
				int newline = source.indexOf('\n', offset + token.text().length());
				headerEnd = newline < 0 ? source.length() : newline + 1;
			}
			offset += token.text().length();
		}
		return source.substring(0, headerEnd) + declarations + "\n" + source.substring(headerEnd);
	}

	private static int function(TokenStream tokens, String name) {
		for (int i = 0; i < tokens.size(); i++) {
			if (tokens.get(i).directive() == null && tokens.get(i).identifier(name)) {
				int before = tokens.significantBefore(i);
				if (before >= 0 && tokens.get(before).identifier("void")) {
					return i;
				}
			}
		}
		throw new IllegalArgumentException("Missing terrain function " + name);
	}
}
